 * function with no `react-intl`/hook dependency of its own, the same split the page's existing
 * wishlist-toast handlers already follow. `buildUrl` is what pre-site-prefixes `href` per
 * `ZimmProductCardBaseProps.href`'s own doc comment — `productUrlBuilder` alone has no site/locale
 * awareness (see `overrides/app/components/ui-kits/atoms/zimmNavItem/index.tsx`'s own fix for the
 * same class of bug: an unprefixed href always falls back to the default site on navigation).
 *
 * Returns `null` when there's no usable name or primary image — mirrors `ZimmProductName`'s own
 * "no render without a name" contract, and `ZimmProductCardBaseProps.primaryImage`'s required-ness
 * (a card with neither has nothing to legitimately render).
 */
export const selectProductListCard = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
  buildUrl: (path: string) => string,
): ProductListCardResult | null => {
  const primaryImage = toCardImage(hit.image);
  if (!hit.productName || !primaryImage) return null;

  const { currentPrice, originalPrice } = selectPriceFields(hit, formatPrice);
  // One resolution feeds the gallery, the hover-swap image, and the fallback candidates below —
  // see `selectColourScopedImages`'s own docblock for why. `primaryImage` above is deliberately
  // NOT re-derived from this list: `hit.image` is the store's own separately-configured "search
  // result" image (confirmed via the SDK's own doc comment: "the first image... for the
  // configured viewtype" — not necessarily `medium`, and not necessarily this colour's `medium`
  // group either), so every entry here is a genuinely distinct, fresh fallback candidate, not a
  // re-listing of an image already tried.
  const scopedImages = selectColourScopedImages(hit, resolveRepresentativeColour(hit));

  return {
    id: hit.productId,
    href: buildUrl(productUrlBuilder({ id: hit.productId })),
    name: hit.productName,
    headingLevel: 'h3',
    primaryImage,
    // Ordered backup candidates if `hit.image` itself fails to load — the real, live defect this
    // closes (confirmed against product `4673TS251`, 2026-09-08): a catalog image group can have
    // a broken image sitting ahead of working ones.
    primaryImageFallbacks: scopedImages,
    // The second image in the same colour-scoped sequence — revealed on hover
    // (`ZimmProductCardMedia`'s own `swapOnHover`/`hoverImage` contract). `undefined` when there
    // is no second image, which that component already treats as "no swap".

